 const safeIds=a=>Array.isArray(a)?a.filter(id=>typeof id==='string'&&data.library.items.some(x=>x.id===id)):[];
 state.library={favorites:safeIds(stored?.library?.favorites),known:safeIds(stored?.library?.known),difficult:safeIds(stored?.library?.difficult),notes:stored?.library?.notes&&typeof stored.library.notes==='object'?stored.library.notes:{},hideTranslation:stored?.library?.hideTranslation===true,layout:stored?.library?.layout==='list'?'list':'cards'};
