 let player=null,audioButton=null,playToken=0,audioNextTimer=null,audioContext=null,toastTimer=null,recorder=null,stream=null,recordChunks=[],recordURL=null,recording=false,recordStarted=0,recordTimer=null,enterStep=false;
 const chapters=[{title:'Первые знакомства',first:1,last:7,description:'Имя, город, язык — и первый разговор.'},{title:'Общие интересы',first:8,last:14,description:'Вкусы, причины и повседневные истории.'},{title:'Люди и планы',first:15,last:21,description:'Реагировать, приглашать и договариваться.'},{title:'Твой разговор',first:22,last:30,description:'Прошлое, планы, кафе и беседа без сценария.'}];
 const lesson=()=>data.lessons[state.day-1];
